        eq(window(new ArrayList<>(List.of(1, 2, 3, 4)), 1, 3), List.of(2, 3)));
    test("a write through the window reaches the backing list", () -> {
        var l = new ArrayList<>(List.of(1, 2, 3, 4));
        window(l, 1, 3).set(0, 9);
        eq(l, List.of(1, 9, 3, 4));
