        var l = new ArrayList<>(List.of("a"));
        raises(UnsupportedOperationException.class, () -> readOnlyView(l).add("x"));
        raises(UnsupportedOperationException.class, () -> frozenCopy(l).add("x"));
    });
    test("the view sees a later write by the owner", () -> {
        var l = new ArrayList<>(List.of("a"));
        var view = readOnlyView(l);
        l.add("late");
