public static void main(String[] args) {
    test("peekCount on a missing key is 0 and inserts nothing", () -> {
        var m = new HashMap<String, Integer>(Map.of("a", 3));
        eq(peekCount(m, "missing"), 0);
        eq(m.size(), 1);
    });
    test("peekCount on a present key is its value", () ->
        eq(peekCount(new HashMap<>(Map.of("a", 3)), "a"), 3));
    test("bucketFor creates and stores a bucket that you can fill", () -> {
        var m = new HashMap<String, List<String>>();
        var b = bucketFor(m, "k");
        eq(b, List.of());
        eq(m.size(), 1);
        b.add("x");
        eq(m.get("k"), List.of("x"));
    });
    test("bucketFor twice returns the same bucket (boundary)", () -> {
        var m = new HashMap<String, List<String>>();
        var first = bucketFor(m, "k");
        first.add("x");
        var second = bucketFor(m, "k");
        second.add("y");
        ok(first == second, "the second call must return the stored list");
        eq(m.size(), 1);
        eq(m.get("k").size(), 2);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

