// ─────────────────────────────────────────────────────────────────────────
//  04 · counts in first-seen order                                   ★★☆
//  concepts: LinkedHashMap insertion order · re-put keeps position · counting
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** Count each event; keys iterate in the order each event first appeared. */
    static LinkedHashMap<String, Integer> firstSeenCounts(List<String> events) {
        var counts = new LinkedHashMap<String, Integer>();
        for (String e : events) counts.merge(e, 1, Integer::sum);
        return counts;
    }

    /** The keys of firstSeenCounts, in iteration order. */
    static List<String> keyOrder(List<String> events) {
        return List.copyOf(firstSeenCounts(events).keySet());
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
