import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** Every element, in poll order (ascending, duplicates kept). */
    static List<Integer> drainAscending(Collection<Integer> xs) {
        var pq = new PriorityQueue<Integer>(xs);
        var out = new ArrayList<Integer>();
        while (!pq.isEmpty()) out.add(pq.poll());
        return out;
    }

    /** The first two polls (xs has at least two elements). */
    static List<Integer> smallestTwo(Collection<Integer> xs) {
        var pq = new PriorityQueue<Integer>(xs);
        return List.of(pq.poll(), pq.poll());
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("drainAscending polls in ascending order and keeps duplicates", () ->
            eq(drainAscending(List.of(5, 1, 3, 1)), List.of(1, 1, 3, 5)));
        test("smallestTwo is the first two polls", () ->
            eq(smallestTwo(List.of(7, 2, 9)), List.of(2, 7)));
        test("a heap whose layout is not sorted still polls in order", () -> {
            eq(drainAscending(List.of(3, 1, 2)), List.of(1, 2, 3));
            eq(smallestTwo(List.of(3, 1, 2)), List.of(1, 2));
